export default async function UserDashboard() {
  let preferences = null;

  try {
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store',
    });
    if (res.ok) {
      preferences = await res.json();
    } else {
       console.error('Failed to fetch user preferences:', res.status, res.statusText);
       // Fallback or empty preferences
       preferences = { error: 'Failed to fetch' };
    }
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    preferences = { error: 'Failed to fetch' };
  }

  return (
    <div className="p-4 border rounded shadow-sm">
      <h2 className="text-xl font-bold mb-4">User Dashboard</h2>
      <div className="space-y-2">
        <p><strong>Preferences:</strong></p>
        <pre className="bg-gray-100 p-2 rounded text-sm overflow-auto">
          {JSON.stringify(preferences, null, 2)}
        </pre>
        <p className="text-sm text-gray-500 mt-2">
          (This data is fetched fresh on every request)
        </p>
      </div>
    </div>
  );
}

