}

export default async function UserDashboard() {
  let preferences;

  try {
    // Fetch with no-store to ensure fresh data on every request
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error(`Failed to fetch: ${res.status}`);
    }

    preferences = await res.json();
  } catch {
    // Return default/fallback preferences if fetch fails
    preferences = { 
      theme: 'system', 
      notifications: true, 
      status: 'active' 
    };
  }

  return (
    <div className="p-4 border rounded shadow-sm bg-white">
      <h2 className="text-xl font-bold mb-4">User Dashboard</h2>
      <div className="space-y-2">
        <div className="grid grid-cols-2 gap-2 text-sm">
          <div className="font-semibold">Theme:</div>
          <div>{preferences.theme}</div>
          <div className="font-semibold">Notifications:</div>
          <div>{preferences.notifications ? 'Enabled' : 'Disabled'}</div>
          <div className="font-semibold">Status:</div>
          <div>{preferences.status}</div>
        </div>
        <p className="text-xs text-gray-400 mt-4 italic">
          Data fetched dynamically per request.
        </p>
      </div>
    </div>
  );
}

// Helper to fetch user data
async function getUserPreferences() {
  try {
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store', // Ensure fresh data on every request
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    return res.json();
  } catch (error) {
    // Return fallback data if fetch fails
    return { 
      theme: 'system', 
      notifications: true, 
      status: 'offline',
      fetchError: true
    };
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div className="p-6 border rounded-lg shadow-sm bg-white max-w-md mx-auto mt-8">
      <h2 className="text-2xl font-bold mb-4 text-gray-800">User Dashboard</h2>

      {preferences.fetchError ? (
        <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-4">
          <p className="text-sm text-yellow-700">
            Could not load live preferences. Showing default settings.
          </p>
        </div>
      ) : null}

      <div className="space-y-4">
        <div className="flex justify-between items-center border-b pb-2">
          <span className="font-medium text-gray-600">Theme</span>
          <span className="capitalize px-2 py-1 bg-gray-100 rounded text-sm font-semibold text-gray-800">
            {preferences.theme}
          </span>
        </div>

        <div className="flex justify-between items-center border-b pb-2">
          <span className="font-medium text-gray-600">Notifications</span>
          <span className={`px-2 py-1 rounded text-sm font-semibold ${
            preferences.notifications ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
          }`}>
            {preferences.notifications ? 'Enabled' : 'Disabled'}
          </span>
        </div>

        <div className="flex justify-between items-center">
          <span className="font-medium text-gray-600">Status</span>
          <span className={`px-2 py-1 rounded text-sm font-semibold ${
            preferences.status === 'active' ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'
          }`}>
            {preferences.status}
          </span>
        </div>
      </div>

      <p className="text-xs text-gray-400 mt-6 text-center italic">
        Data fetched dynamically per request via server component.
      </p>
    </div>
  );
}

